import{_ as a,o as i,c as n,a2 as t}from"./chunks/framework.BXzK3EA4.js";const u=JSON.parse('{"title":"Account - My Details","description":"","frontmatter":{"title":"Account - My Details"},"headers":[],"relativePath":"operations-knowledge-base/presales-support/account-my-details.md","filePath":"operations-knowledge-base/presales-support/account-my-details.md","lastUpdated":1794292919000}'),r={name:"operations-knowledge-base/presales-support/account-my-details.md"};function o(s,e,l,c,m,d){return i(),n("div",null,[...e[0]||(e[0]=[t('<h2 id="_1-overview" tabindex="-1">1. Overview <a class="header-anchor" href="#_1-overview" aria-label="Permalink to &quot;1. Overview&quot;">​</a></h2><p>The account information module is designed to provide users with a convenient and personalized account management experience. It includes settings for profile management, email preferences, and notification subscriptions, helping users manage their account information efficiently and receive important updates in a timely manner.</p><h2 id="_2-feature-details" tabindex="-1">2. Feature Details <a class="header-anchor" href="#_2-feature-details" aria-label="Permalink to &quot;2. Feature Details&quot;">​</a></h2><h3 id="_1-account-details" tabindex="-1">(1) Account Details <a class="header-anchor" href="#_1-account-details" aria-label="Permalink to &quot;(1) Account Details&quot;">​</a></h3><p>In this section, users can manage and update their core account information, including:</p><ul><li>Name</li><li>Address</li><li>Email</li><li>Payment method</li><li>Language</li><li>Phone number</li></ul><p>These details are essential for account identification, service configuration, and transaction processing, ensuring that platform services can be delivered accurately to users.</p><h3 id="_2-email-preferences" tabindex="-1">(2) Email Preferences <a class="header-anchor" href="#_2-email-preferences" aria-label="Permalink to &quot;(2) Email Preferences&quot;">​</a></h3><h4 id="general-emails" tabindex="-1">General Emails <a class="header-anchor" href="#general-emails" aria-label="Permalink to &quot;General Emails&quot;">​</a></h4><p>These include all general emails related to your account and serve as the main communication channel for account-related notifications, such as account status updates.</p><h4 id="invoice-emails" tabindex="-1">Invoice Emails <a class="header-anchor" href="#invoice-emails" aria-label="Permalink to &quot;Invoice Emails&quot;">​</a></h4><p>These emails cover new invoice notifications, payment reminders, and overdue notices, helping users stay informed about billing activity and avoid overdue payments.</p><h4 id="support-emails" tabindex="-1">Support Emails <a class="header-anchor" href="#support-emails" aria-label="Permalink to &quot;Support Emails&quot;">​</a></h4><p>Users will receive copies of all support ticket communications, allowing them to stay updated on ticket progress and participate in issue resolution.</p><h4 id="product-emails" tabindex="-1">Product Emails <a class="header-anchor" href="#product-emails" aria-label="Permalink to &quot;Product Emails&quot;">​</a></h4><p>These emails cover key notifications throughout the product lifecycle, including service activation, suspension, and other periodic updates.</p><p>Whether it is the release of new features, service adjustments, or routine service updates, users will be promptly informed of product status changes.</p><h4 id="domain-emails" tabindex="-1">Domain Emails <a class="header-anchor" href="#domain-emails" aria-label="Permalink to &quot;Domain Emails&quot;">​</a></h4><p>These emails focus on key stages of domain management, including registration confirmations, transfer confirmations, and renewal reminders.</p><p>They cover the full domain lifecycle, from initial ownership confirmation and transfer verification to renewal reminders before expiration, helping users maintain domain ownership and avoid unexpected domain issues.</p><h4 id="affiliate-emails" tabindex="-1">Affiliate Emails <a class="header-anchor" href="#affiliate-emails" aria-label="Permalink to &quot;Affiliate Emails&quot;">​</a></h4><p>This category is intended for users participating in the affiliate program. Users will receive updates on affiliate policies, commission settlements, and promotional campaigns, helping them stay informed and maximize their promotional opportunities and earnings.</p><h3 id="_3-join-our-mailing-list" tabindex="-1">(3) Join our mailing list <a class="header-anchor" href="#_3-join-our-mailing-list" aria-label="Permalink to &quot;(3) Join our mailing list&quot;">​</a></h3><p>The platform offers subscription options for news, announcements, and special promotions.</p><p>Users can subscribe by simply selecting the corresponding checkbox. If they wish to unsubscribe later, they can do so at any time, giving them flexible control over marketing communications.</p><h3 id="_4-telegram-notification-subscription-option" tabindex="-1">(4) Telegram notification subscription option <a class="header-anchor" href="#_4-telegram-notification-subscription-option" aria-label="Permalink to &quot;(4) Telegram notification subscription option&quot;">​</a></h3><h4 id="payment-due-reminder" tabindex="-1">Payment Due Reminder <a class="header-anchor" href="#payment-due-reminder" aria-label="Permalink to &quot;Payment Due Reminder&quot;">​</a></h4><p>Receive Telegram notifications when an order invoice is approaching its due date, helping users manage payments and plan ahead.</p><h4 id="equipment-delivery-reminder" tabindex="-1">Equipment Delivery Reminder <a class="header-anchor" href="#equipment-delivery-reminder" aria-label="Permalink to &quot;Equipment Delivery Reminder&quot;">​</a></h4><p>For services involving server deployment or delivery, users will receive advance notifications so they can make the necessary preparations.</p><h4 id="ticket-reply-reminder" tabindex="-1">Ticket Reply Reminder <a class="header-anchor" href="#ticket-reply-reminder" aria-label="Permalink to &quot;Ticket Reply Reminder&quot;">​</a></h4><p>When a support ticket receives a reply, a Telegram notification will be sent immediately, allowing users to follow up promptly on issue resolution and improve communication efficiency.</p><h2 id="_3-save-changes" tabindex="-1">3. Save Changes <a class="header-anchor" href="#_3-save-changes" aria-label="Permalink to &quot;3. Save Changes&quot;">​</a></h2><p>This section serves as the save point after changes are made to the account settings.</p><p>After updating information in “<strong>Account Details”</strong>, “<strong>Email Preferences”</strong>, “<strong>Join our mailing list”</strong>, or “<strong>Telegram notification subscription option”</strong>, users should click the “<strong>Save”</strong> button to ensure the changes are applied.</p><p>This ensures that the account information and preferences are updated according to the user’s needs and remain aligned with their personal usage preferences.</p><p>Through these account management features, the platform provides users with a comprehensive and customizable account management system, giving them greater control over their account information and enhancing the overall user experience.</p>',37)])])}const h=a(r,[["render",o]]);export{u as __pageData,h as default};
